package io.github.ningpp.compat;

import java.nio.charset.StandardCharsets;

/**
 * Replacement for System.Buffers.Text.Utf8Formatter (generated by CSharpToJava converter).
 * Formats values into a UTF-8 byte span (represented as Integer[] holding byte values).
 */
public final class Utf8Formatter {
    private Utf8Formatter() {
    }

    private static final char[] HEX_DIGITS_UPPER = "0123456789ABCDEF".toCharArray();
    private static final char[] HEX_DIGITS_LOWER = "0123456789abcdef".toCharArray();

    private static boolean writeBytes(byte[] bytes, Span<Integer> destination, IntHolder bytesWritten) {
        if (bytes.length > destination.length()) {
            bytesWritten.value = 0;
            return false;
        }
        for (int i = 0; i < bytes.length; i++) {
            destination.set(i, bytes[i] & 0xFF);
        }
        bytesWritten.value = bytes.length;
        return true;
    }

    /** Mirrors Utf8Formatter.TryFormat(int, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(int value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeIntAscii(value, destination, bytesWritten, 0);
    }

    /** Mirrors Utf8Formatter.TryFormat(int, Span&lt;byte&gt;, out int, StandardFormat). */
    public static boolean tryFormat(int value, Span<Integer> destination, IntHolder bytesWritten, StandardFormat format) {
        char symbol = format.getSymbol();
        if (symbol == 'X' || symbol == 'x') {
            int precision = format.getPrecision() & 0xFF;
            return writeIntHexAscii(value, destination, bytesWritten, symbol == 'X',
                    precision == 0xFF ? 0 : precision);
        }
        if (symbol == 'D' || symbol == 'd') {
            int precision = format.getPrecision() & 0xFF;
            return writeIntAscii(value, destination, bytesWritten, precision == 0xFF ? 0 : precision);
        }
        return writeIntAscii(value, destination, bytesWritten, 0);
    }

    /**
     * Writes decimal ASCII digits directly, replacing
     * {@code Integer.toString(value).getBytes(US_ASCII)} plus a per-byte copy loop.
     *
     * <p>Padding is placed to the LEFT of the sign, which is what the previous
     * StringBuilder implementation did ({@code -1} with width 4 gives {@code "00-1"}, not
     * {@code "-001"}). This differs from {@code String.format("%04d")} on purpose: behaviour
     * must not change here.
     */
    private static boolean writeIntAscii(int value, Span<Integer> destination, IntHolder bytesWritten, int minWidth) {
        boolean negative = value < 0;
        long magnitude = Math.abs((long) value);
        char[] reversed = new char[10];
        int digits = 0;
        do {
            reversed[digits++] = (char) ('0' + (int) (magnitude % 10));
            magnitude /= 10;
        } while (magnitude != 0);

        int digitsLength = digits + (negative ? 1 : 0);
        int padding = Math.max(minWidth - digitsLength, 0);
        int total = padding + digitsLength;
        if (total > destination.length()) {
            bytesWritten.value = 0;
            return false;
        }
        int position = 0;
        for (int i = 0; i < padding; i++) {
            destination.set(position++, (int) '0');
        }
        if (negative) {
            destination.set(position++, (int) '-');
        }
        for (int i = digits - 1; i >= 0; i--) {
            destination.set(position++, (int) reversed[i]);
        }
        bytesWritten.value = total;
        return true;
    }

    /**
     * Writes {@code Integer.toHexString(value)} (two's complement for negative values) zero
     * padded on the left to {@code minWidth}, replacing {@code toHexString} + StringBuilder
     * padding + {@code toUpperCase()} + {@code getBytes(US_ASCII)}.
     */
    private static boolean writeIntHexAscii(int value, Span<Integer> destination, IntHolder bytesWritten, boolean upperCase, int minWidth) {
        char[] table = upperCase ? HEX_DIGITS_UPPER : HEX_DIGITS_LOWER;
        char[] digits = new char[8];
        int count = 0;
        boolean started = false;
        for (int shift = 28; shift >= 0; shift -= 4) {
            int nibble = (value >>> shift) & 0xF;
            if (nibble != 0) {
                started = true;
            }
            if (started || shift == 0) {
                digits[count++] = table[nibble];
            }
        }
        int padding = Math.max(minWidth - count, 0);
        int total = padding + count;
        if (total > destination.length()) {
            bytesWritten.value = 0;
            return false;
        }
        for (int i = 0; i < padding; i++) {
            destination.set(i, (int) '0');
        }
        for (int i = 0; i < count; i++) {
            destination.set(padding + i, (int) digits[i]);
        }
        bytesWritten.value = total;
        return true;
    }

    /** Mirrors Utf8Formatter.TryFormat(long, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(long value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Long.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(double, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(double value, Span<Integer> destination, IntHolder bytesWritten) {
        // DoubleHelper, NOT Double.toString: Java always emits a decimal point for an integral
        // double, so 1.0 became "1.0" where .NET's default 'G' format writes "1". Measured:
        // Utf8JsonWriterTests.writeNumber_JsonEncodedText_Default expected {"":1 and got {"":1.0.
        return writeBytes(DoubleHelper.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(float, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(float value, Span<Integer> destination, IntHolder bytesWritten) {
        // Same reasoning as the double overload, plus one of its own: Float.toString already gives
        // the float's shortest round-trip digits, and widening to double first would print the
        // float's exact binary value instead (0.1f -> 0.10000000149011612).
        return writeBytes(FloatHelper.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(bool, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(boolean value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Boolean.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(Decimal, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(Decimal value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(value.toString().getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(UUID, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(UUID value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(value.toString().getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(DateTime, Span&lt;byte&gt;, out int, StandardFormat). */
    public static boolean tryFormat(CSharpDateTime value, Span<Integer> destination, IntHolder bytesWritten, StandardFormat format) {
        char symbol = format == null ? 'G' : format.getSymbol();
        String text = (symbol == 'O' || symbol == 'o')
            ? value.toString("O")
            : value.toString();
        return writeBytes(text.getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(DateTimeOffset, Span&lt;byte&gt;, out int, StandardFormat). */
    public static boolean tryFormat(CSharpDateTimeOffset value, Span<Integer> destination, IntHolder bytesWritten, StandardFormat format) {
        char symbol = format == null ? 'G' : format.getSymbol();
        String text = (symbol == 'O' || symbol == 'o')
            ? value.toString("O")
            : value.toString();
        return writeBytes(text.getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }
}
